class Solution {
    fun threeEqualParts(arr:IntArray):IntArray{
        val ones=arr.sum();
        if(ones==0)return intArrayOf(0,2);
        if(ones%3!=0)return intArrayOf(-1,-1);
        val part=ones/3;
        var first=-1;
        var second=-1;
        var third=-1;
        var seen=0;
        for(i in arr.indices)if(arr[i]==1){
            seen++;
            if(seen==1)first=i else if(seen==part+1)second=i else if(seen==2*part+1)third=i
        };
        val length=arr.size-third;
        if(first+length>second||second+length>third)return intArrayOf(-1,-1);
        for(i in 0 until length)if(arr[first+i]!=arr[second+i]||arr[first+i]!=arr[third+i])return intArrayOf(-1,-1);
        return intArrayOf(first+length-1,second+length)
    }
}

